{
  "items": [
    {
      "title": "Destatis GENESIS-Online: Official German Economic Statistics",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/",
      "justification": "The Federal Statistical Office of Germany (Destatis) provides comprehensive official economic datasets covering the 2020s. Indicators include gross domestic product (GDP), inflation, consumer prices, employment, wages, industrial production, retail sales, construction, and international trade. The database offers annual, quarterly, and monthly observations, making it particularly useful for examining Germany's economic performance during and after the COVID-19 pandemic. Data can be downloaded in machine-readable formats."
    },
    {
      "title": "Deutsche Bundesbank: Macroeconomic Time Series Database",
      "url_or_doi": "https://www.bundesbank.de/en/statistics/time-series-and-real-time-data",
      "justification": "Provides detailed German macroeconomic and financial statistics, including economic activity, inflation, interest rates, banking indicators, monetary aggregates, credit conditions, and external-sector developments. Its regularly updated time series cover the 2020s and are suitable for analyzing Germany's economic slowdown, inflationary pressures, and monetary conditions. Data are available in CSV and SDMX formats."
    },
    {
      "title": "Eurostat: European Economic and Social Statistics Database",
      "url_or_doi": "https://ec.europa.eu/eurostat/web/main/data/database",
      "justification": "Eurostat provides harmonized economic datasets for Germany and other European countries. Relevant indicators include GDP growth, harmonized consumer price inflation (HICP), unemployment, labor productivity, government debt, fiscal balances, household consumption, and business investment. Monthly, quarterly, and annual datasets covering 2020 onward facilitate comparisons between Germany, the euro area, and other EU member states."
    },
    {
      "title": "European Commission AMECO: Annual Macroeconomic Database",
      "url_or_doi": "https://economy-finance.ec.europa.eu/economic-research-and-databases/economic-databases/ameco-database/download-annual-data-set-macro-economic-database-ameco_en",
      "justification": "The European Commission's AMECO database contains annual macroeconomic indicators for Germany, other EU member states, and selected OECD economies. Variables include real and nominal GDP, economic growth, employment, unemployment, wages, productivity, investment, public debt, government expenditure, and fiscal balances. Particularly useful for studying structural economic changes in Germany throughout the 2020s. Downloadable datasets are available in CSV, TXT, and Excel formats."
    },
    {
      "title": "Deutsche Bundesbank: Long Time Series on Economic Development in Germany",
      "url_or_doi": "https://www.bundesbank.de/en/statistics/sets-of-indicators/long-time-series",
      "justification": "Provides historical and contemporary economic indicators for Germany, including observations from the 2020s. Covers domestic economic activity, labor markets, wages, consumer prices, monetary conditions, public finances, international trade, and exchange rates. Particularly valuable for comparing Germany's economic conditions during 2020–2026 with earlier periods, including the global financial crisis and pre-pandemic economic expansion."
    },
    {
      "title": "Destatis: Short-Term Economic Indicators",
      "url_or_doi": "https://www.destatis.de/EN/Service/OpenData/short-term-indicators.html",
      "justification": "Contains monthly and quarterly indicators of Germany's short-term economic performance, including unemployment and other measures of economic activity. Particularly relevant for analyzing economic fluctuations during the COVID-19 pandemic and subsequent recovery. Historical CSV datasets remain available, while the underlying statistics can also be accessed through GENESIS-Online. The original short-term indicators service was scheduled for discontinuation in October 2026, so GENESIS-Online is the preferred source for updated observations."
    },
    {
      "title": "Deutsche Bundesbank: Economic Activity and Prices Time Series",
      "url_or_doi": "https://statistiken.bundesbank.de/statistiken-en/topics/its",
      "justification": "The Bundesbank's statistics portal provides detailed macroeconomic time series, including economic activity and price indicators relevant to Germany during the 2020s. Suitable for investigating inflation, economic growth, business-cycle developments, and other changes in economic conditions. The portal supports access to individual statistical series and facilitates quantitative analysis using downloadable observations."
    },
    {
      "title": "Deutsche Bundesbank: Macroeconomic Real-Time Database",
      "url_or_doi": "https://www.bundesbank.de/en/statistics/time-series-and-real-time-data",
      "justification": "Provides access to macroeconomic real-time data, including historical releases and revisions of German economic indicators. Relevant variables include national accounts, short-term business indicators, labor-market statistics, and prices. Especially useful for studying how assessments of Germany's economic performance changed during the pandemic, the subsequent inflation surge, and the economic stagnation of the 2020s."
    },
    {
      "title": "Deutsche Bundesbank Research Data and Statistical Datasets",
      "url_or_doi": "https://www.bundesbank.de/en/bundesbank/research/rdsc/research-data",
      "justification": "Offers information about research datasets covering Germany's financial system, banking sector, credit markets, and broader macroeconomic conditions. Relevant resources include bank lending surveys, credit datasets, macroeconomic time series, and monetary statistics. Particularly valuable for researchers investigating financing conditions, banking stability, credit availability, and the transmission of monetary policy during the 2020s. Some detailed research datasets require restricted-access arrangements."
    },
    {
      "title": "Eurostat: Quarterly National Accounts and GDP Statistics",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/view/namq_10_gdp/default/table?lang=en",
      "justification": "Provides quarterly national accounts data for Germany and other European economies, including GDP and its expenditure components. The dataset supports analysis of Germany's economic contraction in 2020, subsequent recovery, and changes in economic activity during the following years. Its quarterly frequency is useful for identifying turning points, recessions, and changes in household consumption, investment, and external demand."
    },
    {
      "title": "Eurostat: Harmonised Index of Consumer Prices (HICP)",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/view/prc_hicp_midx/default/table?lang=en",
      "justification": "Provides monthly harmonized consumer price indices for Germany and other European countries. Particularly useful for analyzing Germany's inflation dynamics during the 2020s, including the effects of pandemic-related supply disruptions, the European energy crisis, and subsequent changes in consumer prices. Harmonized definitions enable comparisons between Germany and other euro-area economies."
    },
    {
      "title": "Eurostat: Monthly Unemployment Statistics",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/view/une_rt_m/default/table?lang=en",
      "justification": "Provides monthly unemployment rates for Germany and other European countries, with breakdowns by age and sex. Useful for examining labor-market conditions during the COVID-19 pandemic, the economic recovery, and subsequent periods of weak economic growth. Harmonized unemployment definitions make the data suitable for cross-country comparisons and longitudinal analysis of Germany's labor market."
    }
  ]
}
